(function(root){
const sources={
 koe:{name:'Dan Koe · Why Productivity Advice Is Ruining Your Life',url:'https://thedankoe.com/letters/why-productivity-advice-is-ruining-your-life/'},
 visual:{name:'McMains & Kastner (2011) · visual attention experiment',url:'https://pubmed.ncbi.nlm.nih.gov/21228167/'},
 breath:{name:'Harvard Health · breath meditation',url:'https://www.health.harvard.edu/mind-and-mood/breath-meditation-a-great-way-to-relieve-stress'},
 resume:{name:'Leroy & Glomb (2018) · ready-to-resume research',url:'https://pubsonline.informs.org/doi/10.1287/orsc.2017.1184'},
 walk:{name:'Oppezzo & Schwartz (2014) · Stanford walking study',url:'https://ed.stanford.edu/news/study-finds-walking-boosts-creativity'},
 woop:{name:'Gabriele Oettingen · official WOOP practice guide',url:'https://woopmylife.org/en/practice'},
 flow:{name:'Durcan et al. (2024) · flow research framework',url:'https://www.nature.com/articles/s44271-024-00115-3'}
};
sources.ness={name:'Anne-Laure Le Cunff · Plus Minus Next, Ness Labs',url:'https://nesslabs.com/plus-minus-next'};
const tips=[
{id:'review',title:'Turn the week into a useful experiment',time:'5 min',kind:'Author’s reflection method',source:'ness',steps:['Write three headings: what worked, what did not, and what to try next.','Include work and life. Pick a change you would like to try next week.'],why:'Le Cunff describes Plus Minus Next as a short weekly review. It is a reflection method, not an experimentally established flow trigger.'},
{id:'clear-space',title:'Clear just the space in front of you',time:'2 min',kind:'Research-informed adaptation',source:'visual',steps:['Move unrelated papers and objects out of your immediate view.','Leave the paper, notebook, and tools for this task. Stop tidying and begin.'],why:'Competing visual stimuli place demands on attention. Clearing a desk is a practical inference from this research; the study did not test desk cleaning or flow.'},
{id:'new-seat',title:'Give your work its own place',time:'Before a session',kind:'Dan Koe’s recommendation',source:'koe',steps:['Try a library desk or café instead of working in bed.','Bring only what the session needs.'],why:'Koe recommends separating work from sleep spaces. You also said new surroundings help you begin. This is a personal experiment, not a proven flow intervention.'},
{id:'music',title:'Try a soundtrack without words',time:'One work block',kind:'Dan Koe’s recommendation',source:'koe',steps:['Choose instrumental music you enjoy, or silence.','Use the same task to notice which helps you stay with it.'],why:'Koe suggests lyric-free music. Effects vary; his recommendation is not evidence that music improves every kind of work.'},
{id:'koe-walk',title:'Take the question for a walk',time:'10 min',kind:'Dan Koe’s recommendation',source:'koe',steps:['After a work block, leave your chair and take a ten-minute walk.','Think about your next task and why you want to do it.'],why:'Koe recommends this break between sessions. It is a practical work-rest routine, not a guaranteed route into flow.'},
{id:'breath',title:'Come back to one breath at a time',time:'1 min to try',kind:'Published mindfulness guidance',source:'breath',steps:['Sit comfortably and notice your normal breathing. Count in, one; out, two; and continue.','When your attention wanders, gently bring it back. No need to force a deep breath.'],why:'Harvard Health describes breath counting and returning attention. The one-minute version is a starting adaptation; it is not a tested minimum dose or a promise of flow.'},
{id:'resume',title:'Leave yourself a way back',time:'1 min',kind:'Studied attention strategy',source:'resume',steps:['Before a meeting or project switch, note where you stopped.','Write the next action, any open problem, and when you will return.'],why:'Ready-to-resume plans reduced attention residue and helped performance on the interrupting task in four studies. Better performance after returning to the original task was not established there.'},
{id:'creative-walk',title:'Stuck for ideas? Change to walking',time:'A short break',kind:'Studied creativity strategy',source:'walk',steps:['When you need several possible approaches, step away for a comfortable walk if you can.','Afterward, capture the options and return to evaluating them.'],why:'Walking helped divergent idea generation in the Stanford experiments. It did not generally improve convergent problem-solving, and the study did not measure flow.'},
{id:'woop',title:'Plan for the moment you usually drift',time:'A few min',kind:'Author’s structured method',source:'woop',steps:['Choose a wish, imagine its best outcome, then identify the main inner obstacle.','Make one plan: “If [obstacle], then I will [specific action].” Picture using it.'],why:'This follows Oettingen’s WOOP order. Example tailored to you: “If I open X while the LLM runs, I will write my own answer in my notes.” It supports follow-through rather than guaranteeing flow.'},
{id:'goal',title:'Turn “do research” into one question',time:'2 min to try',kind:'Flow-informed adaptation',source:'flow',steps:['Write a question this session can address: “Which of these two environments tests pruning pressure?”','Define a visible finish: a comparison paragraph or a short list of tradeoffs.'],why:'Clear goals and usable feedback are common flow conditions. This research example and two-minute setup are adaptations, not a tested protocol.'},
{id:'challenge',title:'Adjust the challenge until you can begin',time:'Before a session',kind:'Flow-informed adaptation',source:'flow',steps:['If the task feels too difficult, isolate one assumption, paragraph, or baseline.','If it feels trivial, add a question that requires your judgment.'],why:'Flow research considers challenge, skill, interest, and choice. Adjusting task scope applies those ideas; there is no universal difficulty ratio that guarantees flow.'}
];
function pick(previous){let pool=tips.filter(t=>t.id!==previous);return pool[Math.floor(Math.random()*pool.length)]||tips[0]}
root.FlowTips={sources,tips,pick};if(typeof module!=='undefined')module.exports=root.FlowTips;
})(typeof window!=='undefined'?window:globalThis);
